entries[12758] = { ["name"] = "Goblin Rocket Helmet", ["text"] = "12.5 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nGoblin Construction Helmet , Goblin Rocket Fuel (4), Mithril Bar (4), Unstable Trigger\nGoblin Rocket Helmet\nBinds when equipped\nHead Cloth\n50 Armor\n+15 Stamina\nDurability 45 / 45\nRequires Engineering\n(235)\nUse: Charge an enemy, knocking it silly for 30 seconds. Also knocks you down, stunning you for a short period of time. Any damage caused will revive the target. (20 Min Cooldown)" }
entries[12759] = { ["name"] = "Gnomish Death Ray", ["text"] = "12.5 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nMithril Tube (2), Unstable Trigger , Essence of Undeath , Ichor of Undeath (4), Inlaid Mithril Cylinder\nBinds when picked up\nTrinket\nUse: The devices charges over time using your life force and then directs a burst of energy at your opponent. (5 Min Cooldown)\n\"Death or Serious Injury may result from use of this device.\"" }
