entries[12899] = { ["name"] = "Gnomish Shrink Ray", ["text"] = "25 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nMithril Tube , Unstable Trigger , Mithril Bar (4), Flask of Mojo (4), Jade (2)\nBinds when equipped\nTrinket\nRequires Engineering\n(205)\nUse: Shrinks the target reducing their attack power by 250. Thats what it usually does anyway..... (5 Min Cooldown)" }
