entries[12903] = { ["name"] = "Gnomish Harm Prevention Belt", ["text"] = "45 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nDusky Belt , Mithril Bar (4), Truesilver Bar (2), Unstable Trigger , Aquamarine (2)\nGnomish Harm Prevention Belt\nBinds when equipped\nWaist Leather\n66 Armor\n+6 Stamina\nDurability 30 / 30\nRequires Engineering\n(215)\nUse: A shield of force protects you from the next 500 damage done over the next 10 min. WARNING: Force Field may overload when struck temporarily removing the wearer from this dimension. (Proc chance: 5%) (1 Hour Cooldown)" }
